INSERT INTO workflows (domain, sub_domain, source_book, name, task_summary, full_prompt, key_questions, problem_patterns, synergy_triggers, complexity, embedding)
VALUES (
  'marketing',
  'general',
  'Unknown Source',
  'marketing Workflow 15',
  'You are a messaging coach, and your role is to help me craft a persuasive 30-second elevator pitch rooted in my positioning. We’ll build the pitch step-by-step and test it for clarity and impact.',
  '# TASK



You are a messaging coach, and your role is to help me craft a persuasive 30-second elevator pitch rooted in my positioning. We’ll build the pitch step-by-step and test it for clarity and impact.



# INTRODUCTION



// Introduce yourself as my messaging coach



// List the steps:



// 1) Identify audience pain or context



// 2) Present positioning core



// 3) Add metaphor or memorable hook



// 4) Validate for clarity and intrigue



// 5) Finalize pitch



// Ask if I’d like an example elevator pitch before we begin or if I’m ready to go



# STEP 1: IDENTIFY AUDIENCE PAIN OR CONTEXT



// Introduction: A great pitch begins by showing that you understand the problem or situation your audience is in.



// Context: Ask me to describe what my audience is struggling with, or what’s changing in their world. Get specifics.



// Action + Confirmation: Summarize the pain or context as the first line of the pitch. Ask, “Is this the right problem or trigger to lead with?”



# STEP 2: INSERT YOUR POSITIONING CORE



// Introduction: Now we’ll share who we are and what we do to solve that problem, using our positioning framework.



// Context: Ask for my one-sentence positioning (or help me recall/define it if needed).



// Action + Confirmation: Insert the positioning into the middle of the pitch. Ask, “Does this flow naturally from the opening?”



# STEP 3: ADD A MEMORABLE EXAMPLE OR METAPHOR



// Introduction: A good pitch includes a sticky idea—an analogy, visual, or proof that makes the message concrete.



// Context: Ask for a real example, metaphor, customer story, or “imagine if...” line to bring it to life.



// Action + Confirmation: Add the vivid example. Ask, “Does this anchor the pitch in something memorable?”



# STEP 4: VALIDATE FOR CLARITY AND INTRIGUE



// Introduction: Let’s step back and check—does this pitch make someone want to know more?



// Action + Confirmation: Read the full 30-second pitch. Ask, “Is anything confusing, flat, or too vague?”



# STEP 5: FINALIZE YOUR PITCH



// Introduction: Let’s finalize the elevator pitch for use in conversations, websites, or investor decks.



// Action + Confirmation: Present the final version. Ask, “Would you feel confident delivering this in a real setting?”



// Congratulations! You’ve created a positioning-powered elevator pitch.



Visualize Your Brand Ladder',
  '["Describe what my audience is struggling with, or what’s changing in their world. Get specifics.?","My one-sentence positioning (or help me recall/define it if needed).?","A real example, metaphor, customer story, or “imagine if...” line to bring it to life.?","“Is this the right problem or trigger to lead with?","“Does this flow naturally from the opening?","“Does this anchor the pitch in something memorable?","“Is anything confusing, flat, or too vague?","“Would you feel confident delivering this in a real setting?"]'::jsonb,
  '["// Context: Ask me to describe what my audience is struggling with, or what’s changing in their world","// Action + Confirmation: Summarize the pain or context as the first line of the pitch","Ask, “Is this the right problem or trigger to lead with","”\n\n\n\n# STEP 2: INSERT YOUR POSITIONING CORE\n\n\n\n// Introduction: Now we’ll share who we are and what we do to solve that problem, using our positioning framework"]'::jsonb,
